INSERT INTO public.trustradius_sap_reviews (id, review_url, title, reviewer_name, published_at, rating, pros, cons, created_at, updated_at) VALUES (56, 'https://www.trustradius.com/reviews/sap-analytics-cloud-2026-03-17-16-31-39', 'SAP Analytics Cloud', 'Verified User', '2026-03-18 15:07:34.837000', 10, e'Pros: Standarized Templates
